/** S016_L422_B01SXCTE IN S016L422, opción 01. */
@Component
@RequiredArgsConstructor
class ClienteS016 {
    private final ClientesApi s016;          // servicio que reemplaza a la librería S016L422
    private final MonitorP280 monitor;
    private final Contadores contadores;

    Optional<DatosCliente> consulta(String numCliente) {
        RespuestaCliente r = s016.buscaPorNumero(numCliente, 1);
        if (r.error() == 0 && numCliente.equals(r.numCliente())) {
            return Optional.of(r.datos());
        }
        contadores.error();
        monitor.errorS016(r, numCliente);    // 200211-GRABA-ERR-S016, id 4
        return Optional.empty();
    }
}

/** 200220-VALIDA-DATOS: se actualiza si cualquiera de los tres datos difiere. */
boolean difiere(DatosCliente cte, ControlDepRet b52) {
    boolean igual = cte.csiAlterno() == b52.csi()
                 && cte.tipoPersona() == b52.tipoPersona()
                 && cte.ubicacionGeo() == b52.ubicacionGeo();
    if (igual) contadores.noActualizado();
    return !igual;
}

@Component
@RequiredArgsConstructor
class ActualizadorB52 {

    private final ControlDepRetRepository repo;   // S500B52CTRLDEPRET
    private final Contadores contadores;
    private final MonitorP280 monitor;

    /** 200230-ACTUALIZA-BD52 + 300233-MUEVE-DATOS-BD52. */
    @Retryable(retryFor = PessimisticLockingFailureException.class,
               maxAttempts = 2, backoff = @Backoff(delay = 2_000))     // WKS-INT-LOOK = 2, WAIT (2)
    @Transactional
    public void actualiza(ControlDepRet b52, DatosCliente cte, LocalDate fechaProceso) {
        ControlDepRet bloqueado = repo.findWithLockById(b52.id()).orElseThrow();  // LOCK
        bloqueado.setFecUpdate(fechaProceso);                // B52-FEC-UPDATE
        bloqueado.setCsi(cte.csiAlterno());                  // B52-CSI
        bloqueado.setTipoPersona(cte.tipoPersona());         // B52-TIP-PER
        bloqueado.setUbicacionGeo(cte.ubicacionGeo());       // B52-UBI-GEO
        contadores.actualizado();                            // STORE + END-TRANSACTION
    }

    /** Dos deadlocks seguidos: se registra y se sigue con el siguiente registro. */
    @Recover
    public void deadlockPersistente(PessimisticLockingFailureException e, ControlDepRet b52,
                                    DatosCliente cte, LocalDate fecha) {
        contadores.error();
        monitor.deadlock(b52.numCliente());                  // 300232-DEADLOCK-BASE, id 20
    }
}

@Configuration
class ReporteErroresConfig {

    /** 50001000-PROC-ARCL050P280: dos lecturas, un SORT y el listado. */
    @Bean
    Step consolidaErrores(JobRepository repo, PlatformTransactionManager tx,
                          ItemReader<ErrorConsolidado> erroresL050Y280,     // L050 de 6 días hábiles + P280
                          ListItemWriter<ErrorConsolidado> temporal) {
        return new StepBuilder("consolidaErrores", repo)
                .<ErrorConsolidado, ErrorConsolidado>chunk(32, tx)          // BLOCK 32 del temporal
                .reader(erroresL050Y280)
                .writer(temporal)
                .build();
    }

    @Bean
    Tasklet reporteErrores(ListItemWriter<ErrorConsolidado> temporal, ReporteJasper jasper,
                           P280Properties props, ContextoCsi csi) {
        return (contribution, ctx) -> {
            List<ErrorConsolidado> errores = new ArrayList<>(temporal.getWrittenItems());
            Collections.sort(errores);                                      // SORT SD-ARCERR
            Map<String, Object> p = Map.of("csi", csi.numero(), "fechaInicio", csi.fechaInicioL050());
            byte[] pdf = errores.isEmpty()
                    ? jasper.render("p280-sin-informacion.jrxml", p, List.of())   // 50001600-IMP-VACIO
                    : jasper.render("p280-errores.jrxml", p, errores);
            jasper.publica(tituloReporte(props.reporte().titulo(), csi.numero(),
                    csi.fechaMaquinaInicio(), ctx.getStepContext().getJobInstanceId()), pdf);
            return RepeatStatus.FINISHED;
        };
    }
}

/** 50001200/1201/1202: hasta 14 copias por día y hasta 9999 secuencias por copia. */
@Bean
@StepScope
MultiResourceItemReader<ErrorConsolidado> erroresL050(AlmacenArchivos almacen, ContextoCsi csi,
                                                      CalendarioBancario cal, L050LineMapper mapper) {
    List<Resource> archivos = new ArrayList<>();
    for (LocalDate f = csi.fechaInicioL050(); !f.isAfter(csi.fechaMaquinaInicio()); f = cal.siguiente(f)) {
        for (int cop = 1; cop <= 14; cop++) {
            for (int sec = 1; sec <= 9999; sec++) {
                // S500/FILE/INTS/50004S01/{csi}/{fecha}/PROBL050ASINC/{cop}/{sec}
                Optional<Resource> r = almacen.busca(TitulosMonitor.l050(csi.numero(), f, cop, sec));
                if (r.isEmpty()) break;              // MOVE 10000 TO WS-L050-SEC: la primera ausente corta
                archivos.add(r.get());
            }
        }
    }
    var lector = new MultiResourceItemReader<ErrorConsolidado>();
    lector.setResources(archivos.toArray(Resource[]::new));
    lector.setComparator((a, b) -> 0);               // conservar el orden de descubrimiento
    lector.setDelegate(new FlatFileItemReaderBuilder<ErrorConsolidado>()
            .name("probL050").lineMapper(mapper).build());
    return lector;
}

